function CartFromB64(t) {
	return new Cartridge(atob(t).split('').map(c => c.charCodeAt(0)));
}

Cart = new Cartridge(rom);

Power();

const cvs = document.getElementById('screen');
const ctx = cvs.getContext('2d');
const img = ctx.createImageData(256, 240);
const img2 = ctx.createImageData(256*8, 240);

document.addEventListener('keydown', function(e) {
	switch(e.code) {
		case 'KeyX':
		ControllerPort1 |= 0x80;
		break;
		case 'KeyZ':
		ControllerPort1 |= 0x40;
		break;
		case 'ShiftRight':
		ControllerPort1 |= 0x20;
		break;
		case 'Enter':
		ControllerPort1 |= 0x10;
		break;
		case 'ArrowUp':
		ControllerPort1 |= 0x08;
		break;
		case 'ArrowDown':
		ControllerPort1 |= 0x04;
		break;
		case 'ArrowLeft':
		ControllerPort1 |= 0x02;
		break;
		case 'ArrowRight':
		ControllerPort1 |= 0x01;
		break;
	}
})

document.addEventListener('keyup', function(e) {
	switch(e.code) {
		case 'KeyX':
		ControllerPort1 &= ~0x80;
		break;
		case 'KeyZ':
		ControllerPort1 &= ~0x40;
		break;
		case 'ShiftRight':
		ControllerPort1 &= ~0x20;
		break;
		case 'Enter':
		ControllerPort1 &= ~0x10;
		break;
		case 'ArrowUp':
		ControllerPort1 &= ~0x08;
		break;
		case 'ArrowDown':
		ControllerPort1 &= ~0x04;
		break;
		case 'ArrowLeft':
		ControllerPort1 &= ~0x02;
		break;
		case 'ArrowRight':
		ControllerPort1 &= ~0x01;
		break;
	}
})

setInterval(function() {
	//_CoreFrameAdvance();
	
	if (PPU_DecodeSignal) {
		cvs.width = 256*8;
		for (let i = 0; i < img2.data.length; i++) {
			img2.data[i] = NTSCScreen[i];
		}
		
		ctx.putImageData(img2, 0, 0);
	} else {
		cvs.width = 256;
		for (let i = 0; i < img.data.length; i++) {
			img.data[i] = Screen[i];
		}
		
		ctx.putImageData(img, 0, 0);
	}
}, 1);